<?php
 namespace QQWorld\Captcha\Observer; use QQWorld\Framework\Event\ObserverInterface; class CheckUserForgotPasswordBackendObserver implements ObserverInterface { protected $_helper; protected $captchaStringResolver; protected $_session; protected $_actionFlag; protected $messageManager; public function __construct( \QQWorld\Captcha\Helper\Data $helper, CaptchaStringResolver $captchaStringResolver, \QQWorld\Framework\Session\SessionManagerInterface $session, \QQWorld\Framework\App\ActionFlag $actionFlag, \QQWorld\Framework\Message\ManagerInterface $messageManager ) { $this->_helper = $helper; $this->captchaStringResolver = $captchaStringResolver; $this->_session = $session; $this->_actionFlag = $actionFlag; $this->messageManager = $messageManager; } public function execute(\QQWorld\Framework\Event\Observer $observer) { $formId = 'backend_forgotpassword'; $captchaModel = $this->_helper->getCaptcha($formId); $controller = $observer->getControllerAction(); $email = (string)$observer->getControllerAction()->getRequest()->getParam('email'); $params = $observer->getControllerAction()->getRequest()->getParams(); if (!empty($email) && !empty($params)) { if ($captchaModel->isRequired()) { if (!$captchaModel->isCorrect($this->captchaStringResolver->resolve($controller->getRequest(), $formId)) ) { $this->_session->setEmail((string)$controller->getRequest()->getPost('email')); $this->_actionFlag->set('', \QQWorld\Framework\App\Action\Action::FLAG_NO_DISPATCH, true); $this->messageManager->addError(__('Incorrect CAPTCHA')); $controller->getResponse()->setRedirect( $controller->getUrl('*/*/forgotpassword', ['_nosecret' => true]) ); } } } return $this; } } 